ROOT=Path(__file__).parent;BASE=ROOT.parent/'bigodds-wide';HIST=ROOT.parent/'bigodds-history'
r=json.loads((ROOT/'results.json').read_text());a=json.loads((ROOT/'audit.json').read_text());alt=json.loads((ROOT/'alternatives.json').read_text());L=json.loads((BASE/'legs.json').read_text());esc=html.escape
labels={'1':'Casa vence','2':'Visitante vence','1X':'1X','X2':'X2','O15':'+1,5 golos','O25':'+2,5 golos','O35':'+3,5 golos','U15':'−1,5 golos','U25':'−2,5 golos','U35':'−3,5 golos','BY':'Ambas marcam','BN':'Ambas não marcam'}
def num(x):return '—' if x is None else f'{x:.2f}'.replace('.',',')
def status(hit):return '✓ Ganha' if hit else '× Perdida'
def table(headers,rows):return '<div class="scroll"><table><thead><tr>'+''.join('<th>'+esc(h)+'</th>' for h in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+esc(str(c))+'</td>' for c in row)+'</tr>' for row in rows)+'</tbody></table></div>'
def statrow(name,v):return [name,f"{v['wins']}/{v['n']}",num(100*v['rate'])+'%' if v['rate'] is not None else '—',num(v['mean_odd'])]
def tickets(title,ts):
 out='<h2>'+esc(title)+'</h2>'
 for t in ts:
  out+='<details><summary>'+esc(t['start']+' · '+status(t['hit'])+' · odd'+num(t['odd'])+' · '+t['book']+' · '+str(len(t['legs']))+' seleções')+'</summary>'
  out+=table(['Lisboa','Jogo','Mercado','Odd','Resultado','Acerto'],[[datetime.datetime.fromtimestamp(L[i]['kickoff']/1000,ZoneInfo('Europe/Lisbon')).strftime('%d/%m %H:%M'),L[i]['home']+' – '+L[i]['away'],labels.get(L[i]['market'],L[i]['market']),num(L[i]['odd']),L[i]['score'],'✓' if L[i]['hit'] else '×'] for i in sorted(t['legs'],key=lambda i:(L[i]['kickoff'],L[i]['id']))])+'</details>'
 return out
x=r['leaders']['xg_full'];n=alt['alternatives']['no_unders'];tr=r['leaders']['xg_train']
body='<h1>Big Odds · Pesquisa alargada com xG</h1><p>06/11/2026 · Estudo offline · Nenhuma alteração de produção</p><h2>Conclusão</h2><p><strong>1 026 432 configurações avaliadas. Encontrámos hipóteses com melhor acerto retrospetivo, mas nenhuma melhoria suficientemente validada para substituir automaticamente o motor público.</strong></p>'
body+='<h2>Melhores resultados no período completo · escolhidos depois de ver o período</h2>'+table(['Hipótese','Ganhas','Acerto','Odd média'],[statrow('Referência anterior, sem xG',{'n':11,'wins':6,'rate':6/11,'mean_odd':9.602332822402648}),statrow('Melhor com xG · admite unders e sentido variável entre janelas',x['all']),statrow('Mesma regra da anterior, sem contributo numérico xG',a['matched_no_xg']['all']),statrow('Com xG, sem unders e com sentido analítico antes da odd',n['all']),statrow('Mesma regra sem unders, retirando o contributo xG',n['matched_no_xg']['all'])])
body+='<p>Os denominadores variam por horizonte e por ausência de boletim elegível. O original usava janelas de dois dias; as candidatas xG acima usam três. As comparações sem contributo xG mantêm os mesmos parâmetros e filtros de cobertura, permitindo isolar melhor o sinal xG. Não se deve interpretar a diferença direta entre6/11 e6/9 como uma validação emparelhada.</p>'
body+='<h2>Uma única múltipla ativa · diagnóstico operacional</h2>'+table(['Hipótese','Ganhas','Acerto','Odd média'],[statrow('Melhor candidata xG',a['sequential_xg_full']['all']),statrow('Candidata xG sem unders',n['sequential']['all'])])
body+='<p>Decisão apenas às08h, sem reutilizar jogos e sem substituir uma múltipla ativa. Para reconstituir o fecho, assumimos resultados finais disponíveis duas horas após o início; não possuímos nesta exportação os relógios reais de liquidação de todos os jogos antigos. Assim,3/4 é apenas um diagnóstico retrospetivo aproximado, não uma validação do funcionamento em produção. Estas regras operacionais foram verificadas nas candidatas selecionadas; não foi feita uma procura exaustiva de todas as políticas sob execução sequencial.</p>'
body+='<h2>Controlo cronológico</h2>'+table(['Candidata','Treino: última data≤29/10','Avaliação: início≥30/10','Como foi escolhida'],[['Melhor xG no período completo',f"{x['train']['wins']}/{x['train']['n']}",f"{x['evaluation']['wins']}/{x['evaluation']['n']}",'Usou os resultados de todo o período; avaliação é apenas descritiva'],['Escolhida só pelo desempenho de treino',f"{tr['train']['wins']}/{tr['train']['n']}",f"{tr['evaluation']['wins']}/{tr['evaluation']['n']}",'Treino ≥3 boletins; maior (vitórias+1)/(n+2), depois maior n e menor ID'],['Sem unders, escolhida no período completo',f"{n['train']['wins']}/{n['train']['n']}",f"{n['evaluation']['wins']}/{n['evaluation']['n']}",'Usou o período completo; não é uma validação independente']])
body+='<p><strong>A regra escolhida apenas pelo treino fez4/4 nessa parte e0/3 na avaliação posterior.</strong> Todo este período já tinha sido visto em estudos anteriores. Mesmo a separação cronológica não constitui um conjunto novo e independente. Janelas de treino/avaliação que cruzam a fronteira são excluídas, e não há jogos comuns entre as duas partes.</p>'
body+='<h2>O que foi testado</h2>'+table(['Dimensão','Valores'],[['Modelos',297],['Meia-vida dos resultados e xG','90,180,365 dias'],['Prior de regularização','2,4,8'],['Peso xG no modelo','10%,25%,50%,75%,100%'],['Amostra xG mínima por condição casa/fora','2 ou4 jogos ponderados; mínimo20 na liga'],['Combinação com referência de mercado','0%,25%,50%'],['Mercados','Todos reais; sem unders; vitórias/duplas hipóteses; golos'],['Probabilidade mínima','50%,65%,80%'],['Odd mínima por seleção','1,05 ou1,20'],['Amostra de resultados mínima','0 ou12'],['Ranking','Probabilidade; eficiência log(p)/log(odd); p×odd'],['Cobertura xG','Fallback para golos ou obrigatória'],['Sentido casa/fora','Livre ou fixado pela análise antes do filtro de odds'],['Horizonte','1,2,3 dias'],['Seleções por boletim','5–12 ou8–12'],['Odd total','Sempre8–15'],['Preços','Apenas odds reais arquivadas; sem estimativas de combos']])
body+='<p>São todas as configurações desta grelha finita. O construtor escolhe o melhor mercado permitido por jogo e avalia prefixos ordenados até12 seleções, comparando casas. Não enumera todas as combinações possíveis de jogos/mercados. Para a melhor candidata retrospetiva exigimos pelo menos8 boletins e xG ativo em pelo menos50% das ocorrências de seleção.</p>'
body+='<h2>Regras das hipóteses guardadas</h2><h3>Melhor no histórico completo</h3><pre>'+esc(json.dumps(x['rule'],ensure_ascii=False,indent=2))+'</pre><p>Nas61 ocorrências de seleção, todas tinham xG suficiente. Inclui15 seleções de menos golos. Há três jogos com1X/X2 em janelas diferentes; por isso não equivale a uma política de publicações sem reutilização e não deve ser promovida diretamente.</p><h3>Hipótese sem unders</h3><pre>'+esc(json.dumps(n['rule'],ensure_ascii=False,indent=2))+'</pre><p>Meia-vida90dias,prior2; com xG suficiente usa o sinal xG no componente do modelo, que depois é combinado50/50 com a referência de mercado. Sem cobertura suficiente, usa o modelo de golos nesse componente. Nas74 ocorrências de seleção do teste com sobreposição,56 tinham xG ativo; na simulação sequencial,19 de28. Não selecionou mercados de menos golos nem ambas não marcam, embora o conjunto permitido sem unders apenas exclua explicitamente U15/U25/U35.</p>'
body+='<h2>Relógios e limitações</h2><ul><li>xG só de jogos já terminados (início+2h) e observado antes da decisão; a ponderação temporal é a data do jogo, não a importação.</li><li>Golos de jogos anteriores usam a mesma disponibilidade reconstruída do estudo original. Revisões e relógios reais do fornecedor não são completamente verificáveis.</li><li>Cobertura parcial: sem xG não se inventam valores. A política required abstém-se; fallback regressa aos golos.</li><li>Preços e resultados conferidos com as exportações arquivadas, sem revalidação externa independente.</li><li>Uma busca de mais de um milhão de regras aumenta muito o risco de encontrar bons resultados por acaso. O melhor resultado histórico não é uma taxa de acerto futura.</li><li>Boletins sobrepostos repetem jogos; as vitórias não são independentes. A amostra sequencial é pequena.</li><li>Não foram alterados o site, o modelo público, os boletins atuais ou o histórico.</li></ul>'
body+=tickets('Melhor candidata xG · nove boletins com sobreposição',x['tickets'])+tickets('Sem unders · dez boletins com sobreposição',n['tickets'])+tickets('Sem unders · quatro boletins sequenciais',n['sequential']['tickets'])
page='<!doctype html><html lang="pt-PT"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Big Odds · Pesquisa xG</title><style>body{font:16px/1.6 system-ui,sans-serif;max-width:1150px;margin:auto;padding:28px;background:#f7fafb;color:#17212b}h1{font-size:30px}h2{margin-top:32px}.scroll,pre{overflow:auto}table{border-collapse:collapse;width:100%;background:white;margin:12px 0}th,td{padding:10px 12px;text-align:left;border-bottom:1px solid #dce4e8}th,summary{background:#e7eff2}summary{padding:14px;cursor:pointer;margin-top:8px;border-radius:8px}pre{font-size:13px;background:#edf2f4;padding:16px}</style>'+body+'</html>'
